INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Observer-Pattern nur für Benachrichtigungen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Ereignisse nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Observer-Pattern?', 3, '[{"text": "Ereignisgesteuerte Kommunikation", "correct": true, "because": "Benachrichtigt Beobachter bei Änderungen"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Observer-Pattern?', 5, '[{"text": "Subject", "correct": true, "because": "Verwaltet Zustand und Beobachter"}, {"text": "Observer", "correct": true, "because": "Reagiert auf Änderungen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Observer werden bei Änderungen informiert. b) Das Pattern ersetzt Command.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Command für Befehle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Observer-Pattern?', 4, '[{"text": "Subject-Zustand", "correct": false, "because": "Kern der Benachrichtigung"}, {"text": "Observer-Registrierung", "correct": false, "because": "Verbindung zum Subject"}, {"text": "UI-Gestaltung", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Observer-Pattern auch ohne Interface funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Abstrakte Klasse möglich"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend Interface nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Subject im Observer-Pattern?', 3, '[{"text": "Zustandsverwalter", "correct": true, "because": "Hält Zustand und Beobachter"}, {"text": "Datenquelle", "correct": false, "because": "Nicht primär"}, {"text": "UI-Steuerung", "correct": false, "because": "Nicht UI-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Observer-Pattern?', 5, '[{"text": "ConcreteObserver", "correct": true, "because": "Implementiert Reaktion"}, {"text": "Subject", "correct": true, "because": "Verwaltet Beobachter"}, {"text": "Datenfluss", "correct": false, "because": "Kein Pattern-Teil"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Observer-Pattern informiert bei Änderungen. b) Es ist nur für UI-Systeme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht UI-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Observer-Pattern?', 4, '[{"text": "Observer-Interface", "correct": false, "because": "Definiert Reaktion"}, {"text": "Subject", "correct": false, "because": "Verwaltet Zustand"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Observer-Pattern nur für Benachrichtigungen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Events generell"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Observer-Pattern?', 4, '[{"text": "Lose Kopplung", "correct": true, "because": "Subject und Observer getrennt"}, {"text": "Ereignisorientierung", "correct": true, "because": "Reaktion auf Änderungen"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Observer-Pattern die Leistung senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead meist minimal"}, {"text": "Ja", "correct": false, "because": "Abhängig von Implementierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Observer-Pattern?', 3, '[{"text": "Effiziente Benachrichtigung", "correct": true, "because": "Kern der Kommunikation"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Flexibilität zählt mehr"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Observer-Pattern nutzt Publish-Subscribe. b) Es erstellt neue Subjects.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Subjects bleiben bestehen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Szenarien profitieren vom Observer-Pattern?', 5, '[{"text": "Echtzeit-Updates", "correct": true, "because": "Änderungen sofort melden"}, {"text": "Event-Handling", "correct": true, "because": "Reaktion auf Ereignisse"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "Hardwareplanung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Observer-Pattern unwichtig?', 3, '[{"text": "Subject-Zustand", "correct": false, "because": "Kern der Benachrichtigung"}, {"text": "Observer-Update", "correct": false, "because": "Reaktion auf Änderungen"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das Observer-Pattern mehrere Subjects haben?', 3, '[{"text": "Ja", "correct": true, "because": "Unabhängige Subjects möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Observer-Pattern für Tests nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Ereignisse testbar"}, {"text": "Nein", "correct": false, "because": "Testfälle unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für den Beobachter?', 4, '[{"text": "Observer-Interface", "correct": true, "because": "Definiert Reaktion"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "UI-Komponente", "correct": false, "because": "Nicht UI-spezifisch"}]');
